import { apiClient } from './client'
import type { AppointmentType, DoctorSlotsResponse, Hospital, HospitalDoctor } from '../types/models'
export const discoveryApi={getHospitals:async()=>(await apiClient.get<{hospitals:Hospital[]}>('/patient/hospitals')).data.hospitals,getHospitalDoctors:async(id:string)=>(await apiClient.get<{hospital:Hospital;doctors:HospitalDoctor[]}>(`/patient/hospitals/${id}/doctors`)).data,getDoctorSlots:async(id:string,date:string,appointmentType:AppointmentType)=>(await apiClient.get<DoctorSlotsResponse>(`/patient/doctors/${id}/slots`,{params:{date,appointmentType}})).data}
